# Generated by unix/generate.py. RGB prompt colors for owned panes.
tmx_prompt_palette() {
  case "$1" in
    black) TMX_PROMPT_FG='230;230;230'; TMX_PROMPT_BG='0;0;0'; TMX_PROMPT_ACCENT='237;237;237' ;;
    aurora) TMX_PROMPT_FG='225;238;230'; TMX_PROMPT_BG='18;32;27'; TMX_PROMPT_ACCENT='159;228;190' ;;
    ember) TMX_PROMPT_FG='238;225;210'; TMX_PROMPT_BG='27;23;21'; TMX_PROMPT_ACCENT='243;166;107' ;;
    paper) TMX_PROMPT_FG='48;46;42'; TMX_PROMPT_BG='246;242;233'; TMX_PROMPT_ACCENT='41;39;36' ;;
    neon) TMX_PROMPT_FG='234;225;250'; TMX_PROMPT_BG='16;14;27'; TMX_PROMPT_ACCENT='239;136;216' ;;
    midnight) TMX_PROMPT_FG='224;230;245'; TMX_PROMPT_BG='16;19;30'; TMX_PROMPT_ACCENT='117;215;232' ;;
    code) TMX_PROMPT_FG='212;212;212'; TMX_PROMPT_BG='30;30;30'; TMX_PROMPT_ACCENT='79;193;255' ;;
    hacker) TMX_PROMPT_FG='185;255;209'; TMX_PROMPT_BG='2;8;5'; TMX_PROMPT_ACCENT='0;255;136' ;;
    prism) TMX_PROMPT_FG='229;233;255'; TMX_PROMPT_BG='17;19;31'; TMX_PROMPT_ACCENT='125;220;254' ;;
    *) TMX_PROMPT_FG='229;233;255'; TMX_PROMPT_BG='17;19;31'; TMX_PROMPT_ACCENT='125;220;254' ;;
  esac
}
